begin;
update gac_private.checkout_settings set enabled=true where singleton;
do $$declare o uuid;m uuid;g uuid:=extensions.gen_random_uuid();i uuid;j uuid;k uuid;oid uuid;inv text;outcome text;req uuid:=extensions.gen_random_uuid();
begin
 select user_id into strict o from gac_private.owners limit 1;select user_id into strict m from public.gac_profiles where user_id<>o and status='active' limit 1;
 insert into public.gac_collections(id,callsign,quantity,price_cents,state,release_at,recognition_at,is_test)values(g,'CHECKOUT_ROLLBACK_FIXTURE',6,100,'open',now()-interval '1 minute',now()+interval '1 hour',false);
 perform set_config('request.jwt.claims',json_build_object('sub',m,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',m::text,true);set local role authenticated;
 begin perform public.gac_begin_hosted_checkout(g,array[1],true,req);raise exception 'Member bypassed owner pilot';exception when insufficient_privilege then null;end;
 reset role;perform set_config('request.jwt.claims',json_build_object('sub',o,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;
 perform public.gac_hold_number(g,1);perform public.gac_hold_number(g,2);i:=public.gac_begin_hosted_checkout(g,array[2,1],true,req);
 if i<>public.gac_begin_hosted_checkout(g,array[1,2],true,req) then raise exception 'Checkout retry changed ID';end if;
 begin perform public.gac_apply_authorizenet_payment('98765001','anything',200,now(),'capturedPendingSettlement');raise exception 'Member credited purchase';exception when insufficient_privilege then null;end;
 reset role;select invoice into strict inv from gac_private.authorizenet_checkouts where id=i;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
 outcome:=public.gac_apply_authorizenet_payment('98765001',inv,199,now(),'capturedPendingSettlement');if outcome<>'review' then raise exception 'Wrong amount accepted';end if;
 reset role;if exists(select 1 from public.gac_numbers where collection_id=g)then raise exception 'Wrong amount assigned numbers';end if;
 -- Price edits after checkout do not alter the amount agreed at checkout.
 update public.gac_collections set price_cents=150 where id=g;
 set local role service_role;
 outcome:=public.gac_apply_authorizenet_payment('98765001',inv,200,now(),'capturedPendingSettlement');if outcome<>'credited' then raise exception 'Valid payment not credited: %',outcome;end if;
 outcome:=public.gac_apply_authorizenet_payment('98765001',inv,200,now(),'capturedPendingSettlement');if outcome<>'credited' then raise exception 'Retry not idempotent';end if;
 outcome:=public.gac_apply_authorizenet_payment('98765002',inv,200,now(),'capturedPendingSettlement');if outcome<>'review' then raise exception 'Second charge was not flagged';end if;
 reset role;
 if(select count(*) from public.gac_numbers where collection_id=g)<>2 or(select count(*) from public.gac_orders where collection_id=g)<>1 then raise exception 'Duplicate or missing purchase';end if;
 if exists(select 1 from gac_private.number_holds where collection_id=g and edition_number in(1,2))then raise exception 'Purchased holds remain';end if;
 if not exists(select 1 from public.gac_orders where collection_id=g and acknowledgment is not null and digital_logo_path is not null and not is_test) then raise exception 'Receipt or logo missing';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',o,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;
 perform public.gac_hold_number(g,3);j:=public.gac_begin_hosted_checkout(g,array[3],true,extensions.gen_random_uuid());perform public.gac_release_my_numbers(g,3);
 reset role;select invoice into inv from gac_private.authorizenet_checkouts where id=j;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;outcome:=public.gac_apply_authorizenet_payment('98765003',inv,150,now(),'capturedPendingSettlement');if outcome<>'review' then raise exception 'Released hold was credited';end if;
 reset role;perform set_config('request.jwt.claims',json_build_object('sub',o,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',o::text,true);set local role authenticated;
 perform public.gac_hold_number(g,4);k:=public.gac_begin_hosted_checkout(g,array[4],true,extensions.gen_random_uuid());
 reset role;update gac_private.authorizenet_checkouts set expires_at=clock_timestamp()-interval '1 second' where id=k;select invoice into inv from gac_private.authorizenet_checkouts where id=k;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;outcome:=public.gac_apply_authorizenet_payment('98765004',inv,150,now(),'capturedPendingSettlement');if outcome<>'review' then raise exception 'Expired hold was credited';end if;
 reset role;perform set_config('request.jwt.claims',json_build_object('sub',m,'role','authenticated')::text,true);perform set_config('request.jwt.claim.sub',m::text,true);set local role authenticated;
 if exists(select 1 from public.gac_my_hosted_checkout(i))then raise exception 'Member read another checkout';end if;
 begin perform public.gac_owner_payment_reviews();raise exception 'Member read owner reviews';exception when raise_exception then if sqlerrm<>'Owner access required' then raise;end if;end;
 reset role;
 if has_table_privilege('authenticated','gac_private.authorizenet_checkouts','select') or has_table_privilege('anon','gac_private.authorizenet_payment_reviews','select') then raise exception 'Private payment tables exposed';end if;
end $$;
rollback;
